<script setup lang="ts">
import { statusLabels,statuses,type RequestRecord } from '@ellas/shared';
definePageMeta({layout:'admin',middleware:'staff'});useSeo('Solicitudes del equipo','Panel privado de solicitudes, presupuestos y pedidos.');
const route=useRoute();const router=useRouter();const search=ref(String(route.query.q||''));
const query=computed(()=>Object.fromEntries(['q','status','type','from','to','page'].filter(k=>route.query[k]).map(k=>[k,route.query[k]])));
interface Result {requests:RequestRecord[];total:number;pages:number;page:number;summary:{_id:string;count:number}[];emailConfigured:boolean;demoMode:boolean}
const {data,error,pending,refresh}=await useFetch<Result>('/api/admin/requests',{query});
function set(key:string,value:string){void router.push({query:{...route.query,[key]:value||undefined,page:undefined}});}
function count(...values:string[]){return data.value?.summary.filter(s=>values.includes(s._id)).reduce((sum,s)=>sum+s.count,0)||0;}
function date(value:string){return new Intl.DateTimeFormat('es-ES',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(value));}
</script>
<template><div class="admin-title"><div><span class="eyebrow">LO QUE MUEVE A TU EQUIPO</span><h1>Solicitudes.</h1><p>Todo a mano. De la primera consulta al pedido entregado.</p></div><button class="button outline" @click="refresh()"><AppIcon name="Clock" :size="17" /> Actualizar</button></div><div class="admin-stats"><article><span>Nuevas solicitudes</span><strong>{{count('recibido','pendiente_confirmacion')}}</strong><small>Pendientes de primera revisión</small></article><article><span>Presupuestos en marcha</span><strong>{{count('en_revision','presupuestado')}}</strong><small>Propuestas por revisar o aceptar</small></article><article><span>Preparando equipo</span><strong>{{count('confirmado','en_preparacion','listo')}}</strong><small>Pedidos confirmados en proceso</small></article><article class="stat-highlight"><span>Solicitudes registradas</span><strong>{{data?.summary.reduce((sum,s)=>sum+s.count,0)||0}}</strong><small>Incluye el historial de ejemplo</small></article></div><div v-if="data && !data.emailConfigured" class="alert"><AppIcon name="Mail" /> El correo transaccional no está configurado. Las solicitudes se guardan; no se están simulando envíos.</div><section class="admin-list-panel"><div class="admin-list-toolbar"><form class="admin-search" @submit.prevent="set('q',search)"><AppIcon name="Search" :size="18" /><input v-model="search" type="search" aria-label="Buscar solicitudes" placeholder="Número, nombre o empresa…" maxlength="100" /><button type="submit" aria-label="Buscar"><AppIcon name="ArrowRight" :size="18" /></button></form><select :value="route.query.type||''" aria-label="Filtrar por tipo" @change="set('type',($event.target as HTMLSelectElement).value)"><option value="">Todos los tipos</option><option value="presupuesto">Presupuestos</option><option value="pedido">Pedidos</option></select><select :value="route.query.status||''" aria-label="Filtrar por estado" @change="set('status',($event.target as HTMLSelectElement).value)"><option value="">Todos los estados</option><option v-for="status in statuses" :key="status" :value="status">{{statusLabels[status]}}</option></select><label class="date-filter">Desde<input type="date" :value="route.query.from||''" @change="set('from',($event.target as HTMLInputElement).value)" /></label><label class="date-filter">Hasta<input type="date" :value="route.query.to||''" @change="set('to',($event.target as HTMLInputElement).value)" /></label><NuxtLink v-if="Object.keys(query).length" to="/admin/solicitudes" class="text-link">Limpiar <AppIcon name="X" :size="14" /></NuxtLink></div><div v-if="error" class="empty-state"><p>No hemos podido cargar las solicitudes.</p><button class="button dark" @click="refresh()">Reintentar</button></div><div v-else class="table-scroll" :aria-busy="pending"><table class="admin-table"><thead><tr><th>Solicitud / fecha</th><th>Cliente</th><th>Tipo</th><th>Prendas</th><th>Estado</th><th><span class="sr-only">Ver detalle</span></th></tr></thead><tbody><tr v-for="request in data?.requests" :key="request._id"><td><NuxtLink :to="`/admin/solicitudes/${request._id}`" class="request-number">{{request.number}}</NuxtLink><span class="table-secondary">{{date(request.createdAt)}}</span></td><td><strong>{{request.contact.company || request.contact.name}}</strong><span class="table-secondary">{{request.contact.name}} <span v-if="request.demo" class="demo-data">Ejemplo</span></span></td><td class="capitalize">{{request.type}}</td><td>{{request.lines.reduce((sum,l)=>sum+l.quantity,0)}} uds.</td><td><span class="status-badge" :class="`status-${request.status}`">{{statusLabels[request.status]}}</span></td><td><NuxtLink :to="`/admin/solicitudes/${request._id}`" class="icon-button" :aria-label="`Ver ${request.number}`"><AppIcon name="ArrowUpRight" /></NuxtLink></td></tr><tr v-if="!data?.requests.length"><td colspan="6" class="empty-table">No hay solicitudes que coincidan con estos filtros.</td></tr></tbody></table></div><div v-if="data" class="admin-list-footer"><span>{{data.total}} solicitudes</span><nav class="pagination" aria-label="Páginas de solicitudes"><NuxtLink v-if="data.page>1" :to="{query:{...route.query,page:data.page-1}}" aria-label="Página anterior"><AppIcon name="ChevronLeft" /></NuxtLink><span>{{data.page}} / {{data.pages || 1}}</span><NuxtLink v-if="data.page<data.pages" :to="{query:{...route.query,page:data.page+1}}" aria-label="Página siguiente"><AppIcon name="ChevronRight" /></NuxtLink></nav></div></section></template>
